import unittest


class TestDisjointSet(unittest.TestCase):

    def test_initial_elements_are_separate(self):
        ds = DisjointSet(5)
        for i in range(5):
            for j in range(i + 1, 5):
                self.assertFalse(ds.connected(i, j))

    def test_union_connects_elements(self):
        ds = DisjointSet(5)
        ds.union(0, 1)
        self.assertTrue(ds.connected(0, 1))
        self.assertFalse(ds.connected(0, 2))

    def test_transitive_connectivity(self):
        ds = DisjointSet(5)
        ds.union(0, 1)
        ds.union(1, 2)
        self.assertTrue(ds.connected(0, 2))

    def test_union_returns_false_for_same_set(self):
        ds = DisjointSet(3)
        ds.union(0, 1)
        self.assertFalse(ds.union(0, 1))

    def test_union_returns_true_for_new_connection(self):
        ds = DisjointSet(3)
        self.assertTrue(ds.union(0, 1))

    def test_disjoint_components(self):
        ds = DisjointSet(6)
        ds.union(0, 1)
        ds.union(2, 3)
        ds.union(4, 5)
        self.assertTrue(ds.connected(0, 1))
        self.assertTrue(ds.connected(2, 3))
        self.assertTrue(ds.connected(4, 5))
        self.assertFalse(ds.connected(0, 2))
        self.assertFalse(ds.connected(0, 4))
        self.assertFalse(ds.connected(2, 4))

    def test_merge_two_components(self):
        ds = DisjointSet(6)
        ds.union(0, 1)
        ds.union(2, 3)
        ds.union(1, 3)
        self.assertTrue(ds.connected(0, 2))
        self.assertTrue(ds.connected(1, 3))
        self.assertTrue(ds.connected(0, 3))

    def test_find_is_idempotent(self):
        ds = DisjointSet(4)
        ds.union(0, 1)
        ds.union(2, 3)
        r1 = ds.find(1)
        r2 = ds.find(1)
        self.assertEqual(r1, r2)

    def test_single_element(self):
        ds = DisjointSet(1)
        self.assertEqual(ds.find(0), 0)
        self.assertTrue(ds.connected(0, 0))

    def test_all_merged_into_one(self):
        n = 10
        ds = DisjointSet(n)
        for i in range(1, n):
            ds.union(0, i)
        for i in range(n):
            for j in range(n):
                self.assertTrue(ds.connected(i, j))

    def test_large_set(self):
        n = 1000
        ds = DisjointSet(n)
        for i in range(0, n - 1, 2):
            ds.union(i, i + 1)
        for i in range(0, n - 1, 2):
            self.assertTrue(ds.connected(i, i + 1))
        self.assertFalse(ds.connected(0, 3))


if __name__ == "__main__":
    unittest.main()
